    if(s.incoming[id]<quantity)return fail('Na rampe nie je dosť tejto suroviny.');
    if(s.raw[id]+quantity>binCapacity(s,id))return fail('Tento zásobník je plný. Vylepši ho alebo spotrebuj zásoby.');
