    const cost=binUpgradePrice(s,id);if(s.money<cost+50)return fail('Potrebuješ '+(cost+50)+' ₵ vrátane rezervy.');
    s.money-=cost;s.bins[id]++;log(s,'Zásobník '+MATERIALS[id].short+' rozšírený na '+binCapacity(s,id)+' kg · −'+cost+' ₵','upgrade');return ok('Zásobník má teraz '+binCapacity(s,id)+' kg.');
